import "server-only";
// Animated worked-example scenes are generated by a separate, very cheap text
// model, independent of the lesson provider (AI_PROVIDER). Env:
//   SCENE_PROVIDER      "hackclub" | "openrouter". Default: hackclub when
//                       HACKCLUB_API_KEY is set, otherwise openrouter.
//   HACKCLUB_API_KEY / OPENROUTER_API_KEY  the key for the chosen provider
//                       (without one, scenes are skipped silently and the
//                       player falls back to steps derived from `example`)
//   SCENE_MODEL         default "deepseek/deepseek-v4.1-flash" (both
//                       providers list it)
// Never throws: any failure (402 insufficient credits, timeout, bad JSON)
// yields null so lesson generation is never affected.
import { parseScene, type Scene } from "@/lib/lesson-scene";
import { findTextCollisions } from "@/lib/scene-layout";
import {
  callCheapModel,
  cheapFetch,
  cheapKey,
  cheapModel,
  cheapProvider,
  FatalModelError,
  warnOnce as warnOnceShared,
  type Msg,
} from "./cheap-model";
import type { LessonContent } from "@/lib/ai/lessons";
import {
  buildRetryPrompt,
  buildScenePrompt,
  describeCollisions,
  extractJson,
  SCENE_SYSTEM_PROMPT,
  type SceneSectionInput,
} from "./scene-helpers";

const CALL_TIMEOUT_MS = 100_000;
const LESSON_TIMEOUT_MS = 150_000;
const MAX_SECTIONS = 8;
const CONCURRENCY = 4;

function warnOnce(key: string, msg: string) {
  warnOnceShared("scenes", key, msg);
}

async function callModel(messages: Msg[], apiKey: string, model: string, fetchImpl: typeof fetch): Promise<string> {
  return callCheapModel(messages, {
    apiKey,
    model,
    fetchImpl,
    label: "scenes",
    // Keep thinking short and leave plenty of room for the scene itself.
    maxTokens: 8000,
    timeoutMs: CALL_TIMEOUT_MS,
  });
}

export async function generateSceneForSection(
  section: SceneSectionInput,
  opts: { apiKey?: string; model?: string; fetchImpl?: typeof fetch } = {}
): Promise<Scene | null> {
  const apiKey = opts.apiKey ?? cheapKey();
  if (!apiKey) {
    warnOnce("nokey", `No API key for scene provider "${cheapProvider()}"; skipping scene generation.`);
    return null;
  }
  const model = opts.model ?? cheapModel();
  const fetchImpl = opts.fetchImpl ?? cheapFetch();
  const messages: Msg[] = [
    { role: "system", content: SCENE_SYSTEM_PROMPT },
    { role: "user", content: buildScenePrompt(section) },
  ];
  try {
    let softFallback: Scene | null = null;
    for (let attempt = 0; attempt < 2; attempt++) {
      const reply = await callModel(messages, apiKey, model, fetchImpl);
      let reason: string;
      try {
        const scene = parseScene(extractJson(reply));
        if (scene) {
          // parseScene already nudged labels apart; anything left is a real clash.
          const left = findTextCollisions(scene);
          if (!left.length) return scene;
          if (!left.some((c) => c.kind === "hard")) softFallback = scene;
          reason = describeCollisions(left);
        } else reason = "the scene did not pass validation (need captions, elements within the canvas, valid types)";
      } catch (e) {
        reason = `invalid JSON (${e instanceof Error ? e.message : "parse error"})`;
      }
      messages.push({ role: "assistant", content: reply }, { role: "user", content: buildRetryPrompt(reason) });
    }
    // Out of retries: keep a scene whose only problems are soft (label near a line).
    return softFallback;
  } catch (e) {
    if (!(e instanceof FatalModelError)) {
      console.warn("[scenes] generation failed:", e instanceof Error ? e.message : e);
    }
    return null;
  }
}

// Fills exampleScene for sections lacking a valid one. Max 3 concurrent, at
// most 8 sections, ~60s overall; whatever finishes in time is attached.
export async function generateScenesForLesson(
  content: LessonContent,
  subjectName: string,
  opts: { apiKey?: string; model?: string; fetchImpl?: typeof fetch } = {}
): Promise<LessonContent> {
  if (!(opts.apiKey ?? cheapKey())) return content;
  const sections = content.sections ?? [];
  const todo = sections
    .map((s, i) => ({ s, i }))
    .filter(({ s }) => s && !parseScene(s.exampleScene) && s.example?.trim())
    .slice(0, MAX_SECTIONS);
  if (!todo.length) return content;

  const results = new Map<number, Scene>();
  const deadline = Date.now() + LESSON_TIMEOUT_MS;
  let next = 0;
  const worker = async () => {
    while (next < todo.length && Date.now() < deadline) {
      const { s, i } = todo[next++];
      const scene = await generateSceneForSection(
        { heading: s.heading, explanation: s.explanation, example: s.example, subjectName },
        opts
      );
      if (scene) results.set(i, scene);
    }
  };
  let timer: ReturnType<typeof setTimeout> | undefined;
  await Promise.race([
    Promise.all(Array.from({ length: Math.min(CONCURRENCY, todo.length) }, worker)),
    new Promise<void>((r) => { timer = setTimeout(r, LESSON_TIMEOUT_MS); }),
  ]);
  if (timer) clearTimeout(timer);
  if (!results.size) return content;
  return {
    ...content,
    sections: sections.map((s, i) => (results.has(i) ? { ...s, exampleScene: results.get(i)! } : s)),
  };
}
